import assert from "node:assert/strict";
import {createElement} from "react";
import {renderToStaticMarkup} from "react-dom/server";
import type {GeneratedBody} from "../../src/core/generators/definition";
import type {Block} from "../../src/core/types";
import {Legacy2018AutumnSystemsFigure} from "../../src/ui/Legacy2018AutumnSystemsFigures";
import {legacy2018AutumnDataFacts as facts} from "./legacy-2018-autumn-systems-data-review";
const attr=(s:string,k:string)=>{const m=s.match(new RegExp(`(?:^|\\s)${k}="([^"]*)"`));assert(m,`missing ${k}`);return m[1];};
const nums=(s:string,keys:string[])=>keys.map(k=>Number(attr(s,k)));
export function legacy2018AutumnHistorySvg(b:Block){assert(b.type==="diagram"&&b.scene.kind==="source_figure");return renderToStaticMarkup(createElement(Legacy2018AutumnSystemsFigure,{profile:b.scene.profile,values:b.scene.values,caption:b.caption??""}));}
/** Read actual class/attribute text, three boxes, both associations, fixed1s
 * and a/b positions. Blank location determines which side's count is asked. */
export function legacy2018ReadAutumnHistory(svg:string){const f=facts.history,entities=[...svg.matchAll(/<g data-entity="[^"]*">([\s\S]*?)<\/g>/g)].map((m,i)=>{const expected=f.entities[i];assert(expected);const rect=m[1].match(/<rect\b([^>]*)/),divider=m[1].match(/<line\b([^>]*)/);assert(rect&&divider);assert.deepEqual(nums(rect[1],["x","y","width","height"]),[expected.x,50,200,200]);assert.deepEqual(nums(divider[1],["x1","y1","x2","y2"]),[expected.x,105,expected.x+200,105]);const texts=[...m[1].matchAll(/<text\b([^>]*)>([^<]*)<\/text>/g)].map(t=>({text:t[2],xy:nums(t[1],["x","y"])}));assert.deepEqual(texts,[{text:expected.name,xy:[expected.x+100,77.5]},...expected.attributes.map((text,j)=>({text,xy:[expected.x+18,140+j*40]}))]);return{name:texts[0].text,left:expected.x,right:expected.x+200};});assert.equal(entities.length,3);const associations=[...svg.matchAll(/<line\b([^>]*data-association="[^"]*"[^>]*)/g)].map(m=>nums(m[1],["x1","y1","x2","y2"]));assert.deepEqual(associations,f.associations);for(const[x1,y1,x2,y2]of associations){assert.equal(y1,y2);assert(entities.some(e=>e.right===x1));assert(entities.some(e=>e.left===x2));}const labels=[...svg.matchAll(/<text\b([^>]*)>([1ab])<\/text>/g)].map(m=>({text:m[2],x:Number(attr(m[1],"x")),y:Number(attr(m[1],"y"))}));assert.deepEqual(labels,f.multiplicityLabels);const blanks=[...svg.matchAll(/<g data-blank="[ab]">([\s\S]*?)<\/g>/g)].map(m=>{const r=m[1].match(/<rect\b([^>]*)/);assert(r);return nums(r[1],["x","y","width","height"]);});assert.deepEqual(blanks,[[300,105,48,38],[592,105,48,38]]);assert(Math.abs(labels[2].x-entities[1].left)<Math.abs(labels[2].x-entities[0].right));assert(Math.abs(labels[3].x-entities[1].right)<Math.abs(labels[3].x-entities[2].left));return{aCountsFor:entities[0].name,bCountsFor:entities[2].name,historyEntity:entities[1].name};}
/** Enumerate2 departments,3 employees, all current assignments and all6
 * possible employee/department history edges. Current membership must appear
 * in history; an employee declared never-assigned has no history. */
export function legacy2018AutumnHistoryRelations(requireDepartment:boolean,requireEmployee:boolean){const rows:{department:number[];employee:number[]}[]=[];for(let assign=0;assign<27;assign++){const current=[assign%3-1,Math.floor(assign/3)%3-1,Math.floor(assign/9)%3-1];if(requireEmployee&&current.includes(-1))continue;if(requireDepartment&&[0,1].some(d=>!current.includes(d)))continue;for(let mask=0;mask<64;mask++){const history=Array.from({length:6},(_,i)=>({employee:Math.floor(i/2),department:i%2})).filter((_,i)=>Boolean((mask>>i)&1));if(current.some((d,e)=>d>=0?!history.some(h=>h.employee===e&&h.department===d):history.some(h=>h.employee===e)))continue;rows.push({department:[0,1].map(d=>history.filter(h=>h.department===d).length),employee:[0,1,2].map(e=>history.filter(h=>h.employee===e).length)});}}assert(rows.length);const minimums=[Math.min(...rows.flatMap(r=>r.department)),Math.min(...rows.flatMap(r=>r.employee))];return{models:rows.length,minimums};}
const paragraph=(b:Block)=>{assert(b.type==="paragraph");return b.text;};
export function legacy2018AutumnDataOracle(source:string,b:GeneratedBody,v:number[]){if(source===facts.history.source){const f=facts.history;assert.equal(v.length,2);assert(v.every(n=>n===0||n===1));assert.equal(b.prompt.length,6);assert.deepEqual(b.prompt.slice(0,5).map(paragraph),[f.stem,"〔条件〕",f.department[v[0]],f.employee[v[1]],f.record]);const figure=b.prompt[5];assert(figure.type==="diagram"&&figure.scene.kind==="source_figure");assert.equal(figure.scene.profile,"legacy-2018-autumn-membership-history");assert.deepEqual(figure.scene.values,[0]);assert.deepEqual(legacy2018ReadAutumnHistory(legacy2018AutumnHistorySvg(figure)),{aCountsFor:"部門",bCountsFor:"社員",historyEntity:"所属履歴"});for(const term of["部門コード","部門名","開始日","終了日","社員コード","氏名","空欄a","空欄b"])assert(figure.alt?.includes(term));const model=legacy2018AutumnHistoryRelations(b.prompt[2].type==="paragraph"&&b.prompt[2].text===f.department[1],b.prompt[3].type==="paragraph"&&b.prompt[3].text===f.employee[1]),at=v[0]*2+v[1];assert.equal(model.models,f.modelCounts[at]);assert.deepEqual(model.minimums,f.minimums[at]);assert.deepEqual(b.choices.map(bs=>{assert.equal(bs.length,1);const t=bs[0];assert(t.type==="table");assert.deepEqual(t.columns,["a","b"]);assert.equal(t.rows.length,1);return t.rows[0];}),f.pairs);const correct=f.pairs.map(pair=>pair.every((s,i)=>s===`${model.minimums[i]}..*`));assert.equal(correct.filter(Boolean).length,1);assert.equal(b.correctIndex,correct.indexOf(true));for(const term of["aは一つの部門","bは一人の社員","現在の所属先が一つ","UMLはUnified Modeling Language"])assert(b.explanation.includes(term));return{model,correct};}
 const f=facts.relation;assert.equal(source,f.source);assert.equal(v.length,1);assert(Number.isInteger(v[0])&&v[0]>=0&&v[0]<15);assert.equal(b.prompt.length,4);assert.equal(paragraph(b.prompt[0]),f.stem);const tables=b.prompt.slice(1).map(p=>{assert(p.type==="table");return p;});assert.deepEqual(tables.map(t=>t.caption),["X","Y","Z"]);assert.deepEqual(tables.map(t=>t.columns),[f.xColumns,f.yColumns,f.zColumns]);assert.deepEqual(tables.map(t=>t.rows.length),[6,3,2]);const[x,y,z]=tables,selected=f.selectedStudentNumbers[v[0]];assert.deepEqual(y.rows,f.faculties);assert.deepEqual(x.rows.map(row=>row.slice(0,2)),f.names.map((name,i)=>[String(i+1),name]));assert.deepEqual(x.rows.map(r=>r[2]),f.names.map((_,i)=>selected.includes(i+1)?"B":"A"));const joined=x.rows.flatMap(row=>y.rows.filter(other=>row[x.columns.indexOf("学部コード")]===other[y.columns.indexOf("学部コード")]).map(other=>Object.fromEntries([...x.columns.map((c,i)=>[c,row[i]]),...y.columns.map((c,i)=>[c,other[i]])])));assert.equal(joined.length,6);assert.equal(new Set(joined.map(r=>r["学生番号"])).size,6);const selectedRows=joined.filter(row=>row["学部名"]==="情報学部"),result=selectedRows.map(row=>z.columns.map(c=>row[c]));assert.deepEqual(z.rows,result);assert.equal(selectedRows.length,2);assert.deepEqual(z.rows.map(r=>Number(r[1])),selected);assert.deepEqual(b.choices.map(bs=>{assert.equal(bs.length,1);return paragraph(bs[0]);}),f.choices);const projectedOnly=joined.map(row=>z.columns.map(c=>row[c])),unionCannotRemove=new Set(projectedOnly.map(r=>JSON.stringify(r))).size>z.rows.length,selectionHasExtraColumn=Object.keys(selectedRows[0]).length>z.columns.length,truth=[!unionCannotRemove,!selectionHasExtraColumn,JSON.stringify(result)===JSON.stringify(z.rows),!selectionHasExtraColumn];assert.deepEqual(truth,[false,false,true,false]);assert.equal(b.correctIndex,truth.indexOf(true));for(const id of selected)assert(b.explanation.includes(String(id)));for(const term of["6行","学部コード","選択だけでは","射影だけでは","和は行を加えて"])assert(b.explanation.includes(term));return{joined,result,truth};}
